//! Original Width/Filter/Ring inner DSP with owned native parameter timelines.
//! Source layout and continuously pulled clock are explicit immutable contracts.
#[path="../../piano-live/src/live_timeline.rs"]mod timeline;
#[path="../../piano-live/src/live_sine.rs"]mod sine;
mod biquad;
mod live;
mod tail;
#[cfg(feature="allocation-audit")]mod allocation;
use timeline::LiveTimeline;
const BLOCK:usize=2048;const LANES:usize=7;const EVENTS:usize=128;
#[derive(Clone,Copy)]struct Event{seconds:f64,frame:u64,values:[f64;7]}
pub struct Engine{kind:usize,rate:f64,channels:usize,initial:[f64;7],mask:u32,ready:bool,events:Vec<Event>,head:usize,lanes:[LiveTimeline;LANES],curves:[[f32;128];LANES],filters:[biquad::Biquad;5],sine:sine::Sine,constant:bool,mode:u32,frame:u64,peak:f64,input:[[f32;BLOCK];2],output:[[f32;BLOCK];2]}
impl Engine{
 fn count(kind:usize)->usize{match kind{1=>1,2=>7,3=>2,_=>0}}
 fn defaults(kind:usize)->[f64;7]{match kind{1=>[1.4,0.,0.,0.,0.,0.,0.],2=>[90.,14000.,0.,0.,8000.,0.707,0.],_=>[300.,0.5,0.,0.,0.,0.,0.]}}
 fn valid(kind:usize,values:&[f64;7])->bool{values.iter().all(|v|v.is_finite())&&match kind{1=>(0. ..=2.).contains(&values[0])&&values[1..].iter().all(|v|*v==0.),2=>(20. ..=600.).contains(&values[0])&&(1000. ..=20000.).contains(&values[1])&&(0. ..=1.).contains(&values[2])&&values[2].fract()==0.&&(0. ..=6.).contains(&values[3])&&values[3].fract()==0.&&(20. ..=18000.).contains(&values[4])&&(0.1 ..=20.).contains(&values[5])&&(-24. ..=24.).contains(&values[6]),3=>(20. ..=2000.).contains(&values[0])&&(0. ..=1.).contains(&values[1])&&values[2..].iter().all(|v|*v==0.),_=>false}}
 pub fn new(kind:usize,rate:f64,channels:usize)->Option<Box<Self>>{if Self::count(kind)==0||!rate.is_finite()||rate.fract()!=0.||!(8000. ..=192000.).contains(&rate)||!(1..=2).contains(&channels){return None;}Some(Box::new(Self{kind,rate,channels,initial:Self::defaults(kind),mask:0,ready:false,events:Vec::with_capacity(EVENTS),head:0,lanes:std::array::from_fn(|i|LiveTimeline::new(Self::intrinsic(kind,i),256)),curves:[[0.;128];LANES],filters:[biquad::Biquad::default();5],sine:sine::Sine::new(rate,0.),constant:false,mode:4,frame:0,peak:0.,input:[[0.;BLOCK];2],output:[[0.;BLOCK];2]}))}
 fn intrinsic(kind:usize,lane:usize)->f64{match kind{1=>1.,2=>match lane{0..=4=>350.,5=>0.707,_=>0.},_=>if lane==0{300.}else{1.}}}
 pub fn initial(&mut self,index:usize,value:f64)->bool{if self.ready||index>=Self::count(self.kind){return false;}let mut next=self.initial;next[index]=value;if !Self::valid(self.kind,&next){return false;}self.initial=next;self.mask|=1<<index;true}
 pub fn event(&mut self,seconds:f64,values:[f64;7])->bool{let frame=seconds*self.rate;if self.ready||!seconds.is_finite()||seconds<0.||seconds>3600.||!frame.is_finite()||frame.round()as u64%128!=0||(frame-frame.round()).abs()>4.*f64::EPSILON*frame.abs().max(1.)||!Self::valid(self.kind,&values)||self.events.len()>=EVENTS||self.events.last().is_some_and(|e|e.seconds>seconds){return false;}self.events.push(Event{seconds,frame:frame.round()as u64,values});true}
 fn projected(&self,values:[f64;7])->([Option<f64>;LANES],u32){let mut p=[None;LANES];let mode=if self.kind==2{match values[3]as u32{0=>4,1=>0,2=>1,3=>2,4=>3,5=>5,_=>6}}else{4};match self.kind{1=>{p[0]=Some((1.+values[0])/2.);p[1]=Some((1.-values[0])/2.);},2=>{let open=self.rate*0.45;let clamp=|v:f64|v.clamp(10.,open);if values[3]==0.{p[0]=Some(clamp(values[0]));p[1]=Some(if values[2]>=0.5{clamp(values[0])}else{10.});p[2]=Some(clamp(values[1]));p[3]=Some(if values[2]>=0.5{clamp(values[1])}else{open});p[6]=Some(0.);}else{p[0]=Some(10.);p[1]=Some(10.);p[2]=Some(open);p[3]=Some(open);p[4]=Some(clamp(values[4]));p[5]=Some(values[5]);p[6]=Some(if mode>=5{values[6]}else{0.});}},_=>{p[0]=Some(values[0]);p[1]=Some(values[1]);p[2]=Some(1.-values[1]);}};(p,mode)}
 fn book(&mut self,seconds:f64,values:[f64;7],initial:bool)->bool{let(p,_) =self.projected(values);for(i,v)in p.into_iter().enumerate(){if let Some(v)=v{if !initial{self.lanes[i].prune_for_insert((seconds*self.rate).round());}if !self.lanes[i].add(seconds*self.rate,if initial{0}else{2},v,if initial{0.}else{0.02*self.rate}){return false;}}}true}
 pub fn prepare(&mut self)->bool{if self.ready||self.mask!=(1<<Self::count(self.kind))-1{return false;}if !self.book(0.,self.initial,true){return false;}self.mode=self.projected(self.initial).1;self.ready=true;true}
 fn lanes_count(&self)->usize{match self.kind{1=>2,2=>7,_=>3}}
 pub fn render(&mut self,n:usize)->bool{if !self.ready||n>BLOCK||self.frame+n as u64>self.rate as u64*3600||(0..self.channels).any(|c|self.input[c][..n].iter().any(|v|!v.is_finite())){return false;}self.peak=0.;for i in 0..n{let f=self.frame;if f%128==0{while self.head<self.events.len()&&self.events[self.head].frame<=f{let e=self.events[self.head];if !self.book(e.seconds,e.values,false){return false;}let mode=self.projected(e.values).1;if self.kind==2&&mode!=self.mode{self.filters[4].clear();}self.mode=mode;self.head+=1;}self.constant=!self.lanes[0].accurate(f);for c in 0..self.lanes_count(){self.lanes[c].prepare(f,self.rate);self.curves[c]=self.lanes[c].output;}}let at=f as usize%128;let input=[self.input[0][i],if self.channels==2{self.input[1][i]}else{0.}];let output=match self.kind{1=>{let same=self.curves[0][at];let cross=self.curves[1][at];[input[0]*same+input[1]*cross,input[1]*same+input[0]*cross]},2=>{let mut x=input;for b in 0..5{let kind=if b<2{1}else if b<4{0}else{self.mode};let hz=self.curves[b][at]as f64;let q=if b==4{self.curves[5][at]}else{0.707f32};let gain=if b==4{self.curves[6][at]}else{0.};x=self.filters[b].sample(x,self.channels,kind,hz,q as f64,gain as f64,self.rate);}x},_=>{let carrier=self.sine.tick(self.curves[0][at],f,self.constant,!self.constant);let wet=self.curves[1][at];let dry=self.curves[2][at];[(input[0]*carrier)*wet+input[0]*dry,(input[1]*carrier)*wet+input[1]*dry]}};for ch in 0..2{if !output[ch].is_finite(){return false;}self.output[ch][i]=output[ch];self.peak=self.peak.max(output[ch].abs()as f64);}if f%128==127{for b in &mut self.filters{b.end_quantum();}}self.frame+=1;}true}
 pub fn reset(&mut self)->bool{if !self.ready{return false;}for i in 0..LANES{self.lanes[i].reset(Self::intrinsic(self.kind,i));}self.frame=0;self.peak=0.;self.head=0;self.filters=[biquad::Biquad::default();5];self.sine.reset();self.input.fill([0.;BLOCK]);self.output.fill([0.;BLOCK]);self.ready=false;self.prepare()}
}
fn index(value:f64,max:usize)->Option<usize>{if value.is_finite()&&value.fract()==0.&&value>=0.&&value<=max as f64{Some(value as usize)}else{None}}
#[no_mangle]pub extern "C" fn rack_native_api()->u32{1}
#[no_mangle]pub extern "C" fn rack_native_new(kind:f64,rate:f64,channels:f64)->*mut Engine{let(Some(kind),Some(channels))=(index(kind,3),index(channels,2))else{return std::ptr::null_mut();};Engine::new(kind,rate,channels).map(Box::into_raw).unwrap_or(std::ptr::null_mut())}
#[no_mangle]pub unsafe extern "C" fn rack_native_free(p:*mut Engine){if !p.is_null(){drop(Box::from_raw(p));}}
#[no_mangle]pub extern "C" fn rack_native_initial(p:&mut Engine,id:f64,value:f64)->u32{index(id,6).is_some_and(|i|p.initial(i,value))as u32}
#[no_mangle]pub extern "C" fn rack_native_event(p:&mut Engine,seconds:f64,a:f64,b:f64,c:f64,d:f64,e:f64,f:f64,g:f64)->u32{p.event(seconds,[a,b,c,d,e,f,g])as u32}
#[no_mangle]pub extern "C" fn rack_native_prepare(p:&mut Engine)->u32{p.prepare()as u32}
#[no_mangle]pub extern "C" fn rack_native_input(p:&mut Engine,ch:f64)->*mut f32{let Some(c)=index(ch,1)else{return std::ptr::null_mut();};p.input.get_mut(c).map(|b|b.as_mut_ptr()).unwrap_or(std::ptr::null_mut())}
#[no_mangle]pub extern "C" fn rack_native_output(p:&Engine,ch:f64)->*const f32{let Some(c)=index(ch,1)else{return std::ptr::null();};p.output.get(c).map(|b|b.as_ptr()).unwrap_or(std::ptr::null())}
#[no_mangle]pub extern "C" fn rack_native_render(p:&mut Engine,n:f64)->u32{index(n,BLOCK).is_some_and(|n|p.render(n))as u32}
#[no_mangle]pub extern "C" fn rack_native_reset(p:&mut Engine)->u32{p.reset()as u32}
#[no_mangle]pub extern "C" fn rack_native_stat(p:&Engine,raw:f64)->f64{let Some(i)=index(raw,4)else{return f64::NAN;};match i{0=>p.frame as f64,1=>p.peak,2=>p.sine.phase(),3=>if p.kind==1{2.}else{p.channels as f64},4=>p.mode as f64,_=>0.}}
